SELECT DISTINCT formula
FROM material_entry
ORDER BY formula;

SELECT EXISTS (
  SELECT 1
  FROM material_entry
  WHERE number_of_elements >= 3
) AS has_compounds_with_three_or_more_elements;

SELECT COUNT(*) AS oqmd_entry_count
FROM material_entry
WHERE source_db = 'OQMD';

SELECT DISTINCT formula
FROM material_entry
WHERE chemical_system ~ '(^|-)Ti(-|$)';

SELECT COUNT(DISTINCT entry_id) AS compound_count
FROM structure
WHERE space_group_number = 225;

SELECT EXISTS (
  SELECT 1
  FROM calculation
  WHERE functional IS NOT NULL
    AND functional <> 'GGA-PBE'
) AS has_non_gga_pbe_entries;

SELECT EXISTS (
    SELECT 1
    FROM material_defect md
    JOIN element e ON md.dopant_element_id = e.element_id
    WHERE e.symbol = 'B'
) AS has_b_dopant_compounds;
